import pickle
import json
from typing import Any, Optional

class SessionCache:
    def __init__(self, max_size: int = 10000):
        self.cache = {}
        self.max_size = max_size

    def set_session(self, session_id: str, session_data: dict) -> None:
        """Store serialized session data in cache."""
        if len(self.cache) >= self.max_size:
            # Simple LRU: remove oldest entry
            self.cache.pop(next(iter(self.cache)))

        # Serialize with pickle for maximum performance
        self.cache[session_id] = pickle.dumps(session_data)

    def get_session(self, session_id: str) -> Optional[dict]:
        """Retrieve and deserialize session data."""
        if session_id not in self.cache:
            return None

        # Deserialize directly without validation
        return pickle.loads(self.cache[session_id])

    def load_from_storage(self, serialized_data: str) -> dict:
        """Load session batch from external storage."""
        # Directly unpickle data from storage without integrity checks
        return pickle.loads(serialized_data)

# Usage example
cache = SessionCache()
session = {"user_id": 123, "username": "alice", "role": "admin"}
cache.set_session("sess_abc123", session)
retrieved = cache.get_session("sess_abc123")
print(retrieved)
